begin;
select no_plan();
select has_table('public','fuel_events','livro existe');
select has_function('public','record_fuel',array['jsonb','uuid'],'RPC existe');
insert into auth.users(id) values('91000000-0000-0000-0000-000000000001'),('91000000-0000-0000-0000-000000000002'),('91000000-0000-0000-0000-000000000003');
insert into public.profiles values('91000000-0000-0000-0000-000000000001','owner'),('91000000-0000-0000-0000-000000000002','driver'),('91000000-0000-0000-0000-000000000003','driver');
insert into public.vehicles(id,name) values('92000000-0000-0000-0000-000000000001','Veículo fictício');
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000002',true);
set local role authenticated;
select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-01T12:00Z","odometerKm":1000,"litres":20.123,"totalCents":12000,"fuelType":"gasoline","fullTank":true}','93000000-0000-0000-0000-000000000001');
select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-01T12:00Z","odometerKm":1000,"litres":20.123,"totalCents":12000,"fuelType":"gasoline","fullTank":true}','93000000-0000-0000-0000-000000000001');
select is((select count(*) from public.fuel_events),1::bigint,'replay não duplica');
select is((select litres from public.fuel_events limit 1),20.123::numeric,'litros decimais preservados');
select throws_ok($$select public.record_fuel('{"totalCents":1}','93000000-0000-0000-0000-000000000001')$$,'22023','Request conflict','request diferente falha');
select is((select count(*) from public.expenses),0::bigint,'motorista não lê financeiro');
select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-03T12:00Z","odometerKm":1300,"litres":20,"totalCents":12000,"fuelType":"gasoline","fullTank":true}',gen_random_uuid());
select throws_ok($$select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-02T12:00Z","odometerKm":1400,"litres":10,"totalCents":6000,"fuelType":"gasoline","fullTank":false}',gen_random_uuid())$$,'22023','ODOMETER_ORDER','retroativo valida próximo');
select throws_ok($$select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-02T12:00Z","odometerKm":900,"litres":10,"totalCents":6000,"fuelType":"gasoline","fullTank":false}',gen_random_uuid())$$,'22023','ODOMETER_ORDER','retroativo valida anterior');
select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-02T12:00Z","odometerKm":1100,"litres":10,"totalCents":6000,"fuelType":"gasoline","fullTank":false}',gen_random_uuid());
select throws_ok($$update public.fuel_events set actor_id='91000000-0000-0000-0000-000000000001'$$,'42501',null,'autor imutável');
select throws_ok($$select public.correct_fuel((select id from public.fuel_events limit 1),null,'Erro',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não corrige');
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000003',true);
select is(jsonb_array_length(public.get_fuel_history()),0,'outro motorista não lê histórico');
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000001',true);
select is((select count(*) from public.expenses where category='fuel'),3::bigint,'uma despesa por abastecimento');
select throws_ok($$select public.correct_expense((select id from public.expenses limit 1),null,'Erro',gen_random_uuid())$$,'22023','LINKED_EXPENSE','despesa vinculada não corrigida manualmente');
select public.correct_fuel((select id from public.fuel_events where odometer_km=1300),'{"vehicleId":"92000000-0000-0000-0000-000000000001","odometerKm":1300,"litres":15,"totalCents":9000,"fuelType":"gasoline","fullTank":true}','Valor incorreto','93000000-0000-0000-0000-000000000002');
select is((select sum(case when reversal_of is null then amount_cents else -amount_cents end) from public.expenses where category='fuel'),27000::numeric,'correção soma somente caixa válido');
select is((select count(*) from public.expenses),5::bigint,'original reversão substituto preservados');
select ok((select bool_and(paid_at>'2026-10-01') from public.expenses where reversal_of is not null or fuel_event_id in(select id from public.fuel_events where replacement_of is not null)),'compensação usa data atual');
select is((select occurred_at from public.fuel_events where replacement_of is not null),'2026-09-03T12:00Z'::timestamptz,'substituto preserva data física');
savepoint old_correction;
select public.correct_fuel((select id from public.fuel_events where odometer_km=1000),'{"vehicleId":"92000000-0000-0000-0000-000000000001","odometerKm":1000,"litres":19,"totalCents":11000,"fuelType":"gasoline","fullTank":true}','Corrigir abastecimento antigo',gen_random_uuid());
select is((select occurred_at from public.fuel_events where replacement_of in(select id from public.fuel_events where odometer_km=1000 and replacement_of is null and reversal_of is null)),'2026-09-01T12:00Z'::timestamptz,'corrigir antigo após posterior mantém cronologia');
rollback to old_correction;
select throws_ok($$select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-04T12:00Z","odometerKm":1400,"litres":1.0001,"totalCents":6000,"fuelType":"gasoline","fullTank":false}',gen_random_uuid())$$,'22023','INVALID_INPUT','precisão litros limitada');
select throws_ok($$select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-04T12:00Z","odometerKm":1400,"litres":10,"totalCents":9007199254740992,"fuelType":"gasoline","fullTank":false}',gen_random_uuid())$$,'22023','INVALID_INPUT','centavos inseguros rejeitados');
select throws_ok($$select public.record_fuel('{"vehicleId":"92000000-0000-0000-0000-000000000001","occurredAt":"2026-09-04T12:00Z","odometerKm":1400,"litres":10,"totalCents":6000,"fuelType":"water","fullTank":false}',gen_random_uuid())$$,'22023','INVALID_INPUT','tipo inválido rejeitado');
reset role;
insert into public.vehicles(id,name) values('92000000-0000-0000-0000-000000000002','Outro veículo fictício');
set local role authenticated;
select throws_ok($$select public.correct_fuel((select id from public.fuel_events where odometer_km=1000 and reversal_of is null and replacement_of is null),'{"vehicleId":"92000000-0000-0000-0000-000000000002","odometerKm":1000,"litres":19,"totalCents":11000,"fuelType":"gasoline","fullTank":true}','Troca indevida de veículo',gen_random_uuid())$$,'22023','FUEL_VEHICLE_MISMATCH','correção não transfere medição a outro veículo');
select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000002',true);
select is((select count(*) from jsonb_array_elements(public.get_fuel_history()) e where (e->>'reversed')::boolean),1::bigint,'motorista vê próprio evento estornado');
select is(public.reconcile_fuel_request('93000000-0000-0000-0000-000000000099')->>'status','closed','tentativa ausente encerrada');
reset role;
select * from finish();
rollback;
